var S=function(t,c){return "<details><summary>"+t+"</summary>"+c+"</details>"};
var TP=function(x){return "<div class='tpl'>"+x+"</div>"};
LEGAL.about=["About","<p style='font-size:1.2rem;color:var(--ink)'>Hi. I help new service businesses turn quote requests into booked jobs.</p><h3>Why I built this</h3><p>Most tradespeople are great at the work and were never taught to sell. They lose jobs in the gap between sending a quote and hearing yes. I built this site to give new owners a clear path to starting the business and the words to win customers.</p><h3>My background</h3><p>10 years in sales. The biggest lesson: most jobs aren’t lost to a cheaper quote. They’re lost to silence after the quote, and a friendly follow-up wins many of them back.</p><h3>How I work</h3><p>Everything is remote and written first, so it fits around jobs. I’m based in Europe and work with US businesses. Calls are scheduled for your mornings or after your workday.</p><h3>What I won’t do</h3><p>I won’t promise income, push you into a trade that doesn’t suit you, or give legal or tax advice. I’ll tell you honestly what I think will work.</p><h3>Work with me</h3><p>Start with a free playbook for your trade, or tell me where you lose jobs and I’ll tell you how I’d fix it.</p><div class='cta'><a class='btn' href='#home-contact'>Get the free playbook</a><a class='btn ghost' href='mailto:"+CONTACT+"'>Email me</a></div>"];
LEGAL.sales=["Sales hub","<p>Simple, honest sales scripts for service businesses. Use them as a starting point and put them in your own words. Trade-specific objections are inside each start-up guide (the roofing guide has eight).</p><h3>Four habits behind every script</h3>"+L(["Listen first. Ask what’s going on before you talk price.","Be honest about what you can and can’t do.","Always agree on the next step before the conversation ends.","Follow up. Most quotes go quiet, not “no.”"])+"<h3>The scripts</h3>"+S("1. Answering the first call or message","<p>Goal: sound calm, understand the job, and book a next step. Ask what’s wrong, when they need it done, and for a photo or the address.</p>"+TP("“Thanks for calling [Business], this is [Name]. Tell me what’s going on and I’ll see how we can help.”")+TP("“Can you send me a photo? I can come by Tuesday at 10 or Wednesday at 2. Which works better?”")+"<p>Offer two times, not “whenever works.” It makes booking easier.</p>")+S("2. Presenting a quote","<p>Present by phone or in person when you can, not only by text. Start with their problem, then your solution, then the price, then the next step.</p>"+L(["Offer two or three options (good, better, best) when it fits.","Put scope, price and warranty in writing.","State how long the quote is valid."])+TP("“Here’s what I found, here’s how I’d fix it, and here’s the price. If you’d like to go ahead, I can start Thursday. What questions do you have?”"))+S("3. Following up on quotes","<p>Follow up within 48 hours, again at 5 days, and once more at 10–14 days. Keep each message short, friendly and useful.</p>"+TP("Day 2: “Hi [Name], I wanted to make sure the quote came through. Happy to answer any questions.”")+TP("Day 5: “Hi [Name], checking in on the [job]. I have a spot on [day] if you’d like to get it done.”")+TP("Day 12: “Hi [Name], I’ll close out your quote on Friday so I can free up the schedule. If you’d still like to go ahead, just reply and I’ll hold a spot.”"))+S("4. Closing","<p>Ask directly. Many owners never do. Give a choice between two next steps, not “yes or no.”</p>"+TP("“Would you like to start Monday or Wednesday?”")+"<p>After you ask, stop talking. Silence is okay. If they hesitate, ask what’s holding them back.</p>")+S("5. Handling objections (a simple method)","<p>Acknowledge it, ask a question, answer honestly, then suggest a next step.</p>"+TP("Customer: “That’s more than I expected.” You: “I understand. What number were you hoping for? Let me show you what’s included and where we can adjust.”"))+S("6. Asking for reviews and referrals","<p>Ask right after the job, when they’re happiest. Text a direct review link.</p>"+TP("“Thanks again, [Name]. If you’re happy with the work, would you leave a quick Google review? Here’s the link. And if you know anyone who needs help, I’d appreciate the introduction.”"))+S("7. Handling a “no”","<p>Stay polite and leave the door open. Many people come back.</p>"+TP("“No problem, [Name]. Thanks for considering us. If anything changes, I’m here. Would it be okay if I checked in next month?”"))+"<p style='margin-top:18px'>Want these written for your trade? <a href='#home-contact'>Get the free playbook</a>.</p>"];
var FULL={roofing:{lic:["Rules vary a lot by state. Some states (Florida, Arizona and California, for example) require a state contractor license for roofing. Others (Texas, for example) have no state roofing license, but cities or counties may require registration or permits. Confirm with your state licensing board.","Where a license is required, expect to show experience, pass an exam, and carry insurance and sometimes a bond. This can take weeks or months, so start early.","Many jobs need a local building permit. Some areas also have rules for storm-damage work and door-to-door sales (solicitation permits, cooling-off periods). Check before you knock.","Many states restrict how roofers deal with insurance claims. Never offer to waive a customer’s deductible, because that is illegal in many states.","OSHA fall-protection rules apply once you have employees. Plan for harnesses and training from day one."],cost:[["Business setup (LLC, license, bond)","$300–$2,500"],["General liability insurance","$1,500–$5,000 per year"],["Workers’ compensation","Depends on payroll and state; often the biggest cost once you hire"],["Ladders, safety gear, fall protection","$1,500–$4,000"],["Tools (nailers, compressor, cutters)","$1,500–$4,000"],["Used truck and trailer","$5,000–$20,000 if you don’t already own one"],["Software, website, marketing","$500–$2,500"],["Working capital for materials until customers pay","$3,000–$10,000"]],costnote:"Bare minimum (you own a truck, work solo or with one helper, small repairs) is roughly $8,000–$12,000. A crew-ready start is closer to $25,000–$40,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, get insurance quotes and confirm licensing."],["Weeks 3–4","Set up a Google Business Profile, a simple one-page site and a quote template. Open a supplier account. Photograph every job, even small repairs for friends."],["Month 2","Do 5–10 small repairs for neighbors, friends and landlords. Ask each customer for a review and a referral. Introduce yourself to 10 local realtors and property managers."],["Month 3","Start quoting full replacements. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Roofers price replacements by the square (100 sq ft of roof). Example: a 2,400 sq ft roof with moderate pitch is about 28 squares including waste. If materials and labor cost you about $330 per square, that’s $9,240, plus about $600 for dump fees and permits. Add 25–35% for overhead and profit and the quote lands around $12,300–$13,300. Itemize tear-off, underlayment, shingles, flashing, cleanup and warranty. Your own costs will differ, so treat this as an example.",mistakes:["Underinsuring. One fall or leak claim can end a business with no cover.","Spending one customer’s deposit on another job. Pay for each job’s materials first.","Leaving scope and warranty out of the contract.","Underpricing to win jobs, then losing money on rotted decking. Add a clause for hidden damage priced per sheet.","Chasing storm work without checking local solicitation and insurance-claim rules.","Letting quotes go cold. Many sales happen on the second or third contact."],obj:[["“Your price is higher than the other guy’s.”","“That’s fair, I’d compare too. What’s included in the other quote? Materials, underlayment, warranty and cleanup are where prices differ. I’d rather you choose on what you get than on the number alone.”"],["“I need to get a few more quotes.”","“Totally reasonable. To make it easy, compare the materials brand, underlayment, flashing, warranty and who does the work. I’ll check back Thursday to answer any questions.”"],["“I need to talk to my spouse.”","“Of course, it’s a big decision. What do you think they’ll want to know? I’ll send a one-page summary with photos so you can go through it together.”"],["“Can you do it cheaper?”","“I can adjust the materials or scope to hit a budget. What number are you hoping for? Then I’ll show you what that gets. I won’t cut corners on the parts that keep your roof dry.”"],["“My insurance should pay for it.”","“If it’s storm damage, I can document the roof with photos for your adjuster. I can’t waive your deductible, because that’s against the rules in many states, but I’ll make sure the damage is well documented.”"],["“I’ll wait until next year.”","“Understood. Small leaks can turn into rotted decking, which costs a lot more. Want me to patch the leak now so you have time to plan the replacement?”"],["“How do I know you’ll be around for the warranty?”","“Fair question. Here’s my license and insurance, and local references you can call. I put the warranty in writing so you’re covered either way.”"],["“Why do you need a deposit?”","“The deposit pays for your materials so they’re ordered on time. It’s all in the contract, and the balance is due once the work is finished and you’ve approved it.”"]],faq:[["Can I start with just repairs?","Yes. Repairs build reviews, cash and skill with less risk. Move to full replacements once your estimates are solid and your insurance fits."],["Do I need workers’ comp if I work alone?","It varies by state. Even where it isn’t required for a sole owner, many customers and suppliers ask for it, and it is usually required once you have employees. Check your state."],["How do I get paid?","A common structure is a deposit for materials, a payment when work starts, and the balance on completion. Check your state’s limits on deposits."],["Should I do insurance-claim work?","It can be a big source of jobs, but it has legal rules. Never offer to cover a deductible and don’t act as the homeowner’s adjuster. Learn your state’s rules first."],["How do I compete with big roofers?","Be faster, easier to reach and clearer. Small local roofers win with quick quotes, photos, honest communication and strong reviews."]],tools:["Quoting and invoicing: Jobber, Housecall Pro, or a simple spreadsheet to start.","Measuring: aerial measurement reports (such as EagleView or Hover) or the tools many suppliers offer.","Reviews: a Google Business Profile with a short review link you text after every job.","Scheduling: a shared calendar and a weather app so you can reschedule early."]}};
Object.assign(FULL,{
hvac:{lic:["Rules vary a lot by state. Some states license HVAC contractors statewide: Texas (an air conditioning and refrigeration contractor license from TDLR) and California (a C-20 license from the CSLB), for example. Others, such as New York and Illinois, have no statewide HVAC license, but cities and counties may require their own license or registration. Confirm with your state licensing board.","Where a license is required, expect to document years of experience, pass an exam, and carry insurance and sometimes a bond. Texas asks for 48 months of experience within the last 72, and California asks for four years at journey level plus a $25,000 bond. This can take weeks or months, so start early.","Replacements, new installs and gas or electrical changes usually need a permit and an inspection. Replacements are often sold in the customer’s home, which brings the federal three-day cooling-off rule, and some cities require solicitation permits for door-to-door sales. Check before you knock.","Never vent refrigerant. Federal law requires EPA Section 608 certification to open a refrigerant circuit or buy refrigerant, and certified equipment to recover it. Check what you install, too: new R-410A systems may only use equipment made or imported before 2025, New York has its own stricter deadline, and southern states have higher efficiency minimums for new split systems.","The newer A2L refrigerants (such as R-454B and R-32) are mildly flammable, so get A2L training and use A2L-rated recovery machines and leak detectors. Once you hire, OSHA rules on electrical lockout, ladders and heat stress in attics apply."],cost:[["Business setup (LLC, license and exam fees, bond)","$300–$2,500"],["General liability insurance","$700–$2,500 per year"],["Workers’ compensation","Depends on payroll and state; California requires it for HVAC licensees even with no employees"],["EPA 608 exam, A2L training and safety gear","$150–$800"],["Tools (digital gauges, vacuum pump, micron gauge, A2L-rated recovery machine, leak detector)","$3,000–$8,000"],["Used work van","$10,000–$30,000 if you don’t already own one"],["Software, website, marketing","$500–$2,500"],["Working capital for parts and equipment until customers pay","$2,000–$8,000"]],costnote:"Bare minimum (you already hold the license and EPA 608 card, own a vehicle, and work solo on service and tune-ups) is roughly $7,000–$12,000. An install-ready start with a used van, a full A2L-ready tool set, workers’ comp and a distributor credit line is closer to $30,000–$50,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, get insurance quotes (including workers’ comp) and confirm state and city licensing. If your EPA 608 card doesn’t cover the work you’ll do, take the Universal exam now. Open accounts at two local distributors."],["Weeks 3–4","Build a flat-rate book for your 25 most common repairs, plus a diagnostic fee. Set up a Google Business Profile, a one-page site and scheduling software. Write a simple maintenance plan: two tune-ups a year with priority service."],["Month 2","Do 15–25 tune-ups and service calls for neighbors, friends and landlords. Note each system’s age and photograph the data plate, so you know who will need a replacement soon. Introduce yourself to 10 property managers and realtors."],["Month 3","Start quoting replacements, with a load calculation and two or three options. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off, do more of those, and sign up maintenance-plan customers before the next peak season."]],price:"HVAC companies price repairs from a flat-rate book and replacements per system, sized in tons (1 ton is 12,000 BTU per hour of cooling). Example: replacing a 3-ton split air conditioner (outdoor unit and matching indoor coil) on an existing furnace. If the equipment costs you $3,400, the line set, pad, disconnect and other materials $400, and 16 labor hours (two techs for a day) at $50 an hour $800, that’s $4,600, plus about $250 for the permit and recovering the old refrigerant. That’s $4,850. Add 35–45% for overhead and profit and the quote lands around $6,550–$7,030. Itemize the equipment model numbers and efficiency rating, line set, electrical, permit, refrigerant recovery, load calculation, and the parts and labor warranties. Your own costs will differ, so treat this as an example.",mistakes:["Spending one customer’s deposit on another job’s equipment. Collect the deposit first, order equipment per job, and keep distributor terms current so one slow payer doesn’t freeze your credit line.","Skipping workers’ comp or completed-operations cover. A clogged condensate line can flood a ceiling months after you’ve been paid, and the claim lands on you.","Leaving ductwork, electrical upgrades and warranty registration out of the contract. Say what’s included, what isn’t, and who registers the manufacturer warranty, since many brands set a deadline.","Sizing by rule of thumb and underpricing replacements, then paying for a new line set, pad or electrical upgrade yourself. Do a load calculation, inspect before you quote, and add a clause for hidden problems priced per item.","Installing without a permit, or installing equipment that doesn’t meet your area’s refrigerant or efficiency rules. Inspectors can make you redo it at your cost.","Letting replacement quotes go cold. Many customers decide after the next hot or cold week, and the contractor who followed up gets the call."],obj:[["“The other company quoted less.”","“That’s fair, I’d compare too. Is it the same size and efficiency, with a new coil, line set and permit? That’s where HVAC quotes differ. I’ll leave you a short checklist so you can compare them side by side.”"],["“I want to get a couple more quotes.”","“Makes sense for a system that should last 12–15 years. What will you compare on? Ask each company whether they did a load calculation, what efficiency rating they quoted and who registers the warranty. I’ll call Thursday to answer any questions.”"],["“I need to run it by my spouse.”","“Of course, it’s a big purchase. What will they want to know most, the price or the monthly energy bills? I’ll send a one-page summary with the options and photos of your current system so you can decide together.”"],["“Can you do it for less?”","“I can quote a standard-efficiency option or keep parts that are still in good shape. What budget are you working with? I won’t skip the permit or proper refrigerant work, because that keeps it safe and under warranty.”"],["“Can’t you just add refrigerant?”","“I could, but refrigerant doesn’t get used up, so low refrigerant means a leak. Has it needed a top-up before? I’ll check how fast it’s leaking and show you the price to find and fix it next to the price to replace, so you can choose.”"],["“I’ll wait until it dies completely.”","“I get it, nobody wants to replace something that still runs. How old is it, and has it needed repairs lately? Systems often fail on the hottest day, when installers are booked out. I’ll quote it now so you can plan, and keep it running until you’re ready.”"],["“How do I know you’re not just selling me a new system?”","“Fair question, it happens in this trade. What would help you trust the diagnosis? I’ll show you the readings and photos and price the repair too. If repairing makes more sense, I’ll tell you so.”"],["“Why do you need money up front?”","“The deposit buys your equipment so it’s held for your install date. What payment schedule works for you? It’s all in the contract, and the balance is due once the system is running and you’ve signed off.”"]],faq:[["Can I start with just service and tune-ups?","Yes. Service and maintenance need less equipment and cash, and every tune-up shows you an older system that may need replacing soon. Add replacements once your load calculations, permits and distributor terms are in place."],["Do I need EPA 608 certification if I only do service?","Yes, if the work could release refrigerant, such as adding refrigerant, replacing a valve or recovering it. You also need it to buy refrigerant. Electrical repairs like capacitors and contactors don’t require it, but you’ll hit refrigerant work quickly."],["How do I get paid?","Service calls are usually paid on the spot by card. For replacements, a common structure is a deposit when the customer signs to cover equipment and the balance on completion, or a financing partner who pays you after the job. Check your state’s limits on deposits."],["Should I take home warranty company calls?","They can fill a slow week, but they usually pay set rates below your own, cover only some parts and leave you explaining denials to the homeowner. If you take them, cap them to a small share of your schedule and keep building your own customers."],["How do I compete with big HVAC companies?","Be the honest repair-or-replace option. Big companies often send commissioned salespeople. You can win by showing readings, pricing the repair next to the replacement, answering the phone yourself and running a simple maintenance plan."]],tools:["Quoting and invoicing: Housecall Pro, Jobber or ServiceTitan, or a simple spreadsheet to start.","Load calculation and diagnostics: Manual J software (such as CoolCalc or Wrightsoft) and wireless probes that log readings (such as Fieldpiece or Testo).","Reviews: a Google Business Profile with a short review link you text after every job.","Scheduling: a shared calendar with automatic spring and fall tune-up reminders for maintenance-plan customers, plus a 10-day forecast to plan for heat waves and cold snaps."]},
plumbing:{lic:["Rules vary a lot by state. Many states license plumbers statewide in tiers (apprentice, journeyman, master): Texas (through the State Board of Plumbing Examiners) and California (a C-36 license from the CSLB), for example. Others, such as Pennsylvania, have no statewide plumbing license, but cities like Philadelphia license plumbers locally. Confirm with your state licensing board.","Where a license is required, expect years of supervised work, exams, and insurance and sometimes a bond. Texas, for example, asks for about 8,000 hours of experience before the journeyman exam, and California asks for four years at journey level before a contractor license. This takes years, not weeks, so start early.","Water heaters, re-pipes, sewer lines and gas work usually need a permit and an inspection. Many cities also require contractor registration before they issue permits, and some limit door-to-door sales with solicitation permits. Check locally.","Don’t work beyond your license, and don’t let unlicensed helpers work alone. In licensing states, helpers usually must be registered apprentices under a licensed plumber, and gas lines, backflow testing and medical gas often need an extra endorsement. Skipping the permit on a water heater is common, and it can leave you liable if the heater fails.","OSHA requires cave-in protection (sloping, shoring or a trench box) for trenches 5 feet or deeper, so plan for it on sewer and water line jobs, and call 811 before you dig. Pipes and fittings for drinking water must be lead-free under federal law."],cost:[["Business setup (LLC, license fees, bond, city registration)","$300–$2,500"],["General liability insurance (check it covers water damage)","$1,200–$4,000 per year"],["Workers’ compensation","Depends on payroll and state; registered apprentices are employees, so budget for it with your first helper"],["Safety gear and certifications (backflow, gas)","$300–$2,000"],["Tools (hand and power tools, drain machines, press tool, sewer camera)","$3,000–$15,000"],["Used van with shelving","$10,000–$30,000 if you don’t already own one"],["Software, website, marketing","$500–$2,500"],["Working capital for parts stock and water heaters until customers pay","$2,000–$8,000"]],costnote:"Bare minimum (you already hold the license, own a truck, and work solo on service and repairs with hand tools and a drum machine) is roughly $7,000–$12,000. A van stocked with a sewer camera, press tool and spare water heaters is closer to $30,000–$55,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, and confirm your license covers running a business in your state and city. Get liability quotes that include water damage. Open accounts at two plumbing supply houses."],["Weeks 3–4","Build a flat-rate price book for your 25 most common jobs, with a trip fee and an after-hours rate. Set up a Google Business Profile, a one-page site and a phone number you’ll actually answer. Stock the van for toilets, faucets, drains and supply lines."],["Month 2","Do 15–25 service calls: clogs, running toilets, faucets and leaks. Ask each customer for a review. Introduce yourself to 10 property managers and landlords and give them a direct number. Note the age of every water heater you see."],["Month 3","Start quoting water heater replacements, re-pipes and sewer repairs. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Plumbers quote most work as a flat rate per task from a price book, built from parts, labor hours and extras. Example: replacing a 50-gallon gas water heater. If the heater costs you $750 at the supply house, the expansion tank, gas connector, valves and venting parts $180, and 4 labor hours at $60 an hour $240, that’s $1,170, plus about $150 for the permit and hauling away the old tank. That’s $1,320. Add 40–50% for overhead and profit (the van, stock and unpaid drive time) and the quote lands around $1,850–$1,980. Itemize the heater size and model, code parts (expansion tank, drain pan, venting), permit, haul-away and the labor warranty. Your own costs will differ, so treat this as an example.",mistakes:["Floating parts and water heaters on your own card for slow-paying landlords. Put payment terms in writing, and collect from homeowners on the spot.","Buying a cheap policy that excludes water damage or finished work. A failed fitting can flood a house weeks after you leave, and that’s the claim you most need covered.","Quoting a drain clearing without saying what happens if the line is broken. Write that a camera inspection and repairs are separate, and get approval before extra work.","Underpricing emergencies and old-house surprises. Charge an after-hours rate, and add a clause for corroded or seized pipe found during the job, priced per fitting or per hour.","Skipping permits or letting an unregistered helper work alone. Either can cost you your license and leave you liable if something fails.","Letting quotes go cold. A homeowner who said “not now” to a re-pipe often hires whoever follows up after the next leak."],obj:[["“Another plumber quoted less.”","“That’s fair, I’d compare too. Does their price include the permit, code parts like an expansion tank, hauling away the old heater and a labor warranty? That’s where plumbing quotes differ. Send it over and I’ll mark the differences for you.”"],["“I want to get other quotes first.”","“Sure, a re-pipe is a big job. Which matters more to you, price or how quickly it’s done? When you compare, check the pipe type, number of fixtures, who patches the drywall and whether the permit is included. I’ll check back Friday.”"],["“I have to check with the property owner.”","“Of course, it’s their call. What do they usually need to approve a repair? I’ll send photos, the price and what happens if it waits, so you can forward it today.”"],["“Can you do it cheaper if I buy the part?”","“I can install a part you buy. Which one did you have in mind? I just can’t warranty a part I didn’t supply, so if it fails you’d pay for labor twice. I’ll write up both prices so you can decide.”"],["“I’ll just pour drain cleaner down it.”","“Lots of people try that first. How long has it been slow? Chemical cleaners can damage older pipes and won’t clear roots or a broken line. If it comes back, I’ll clear it and run a camera so you can see what’s really there.”"],["“It’s only a small drip, I’ll deal with it later.”","“Understood, it doesn’t look urgent. Do you know how long it’s been dripping? Slow leaks under a cabinet or slab can rot the floor and grow mold before you see them. I can give you a flat price to fix it today.”"],["“How do I know I won’t get a surprise bill?”","“Fair worry, plumbers hear it a lot. What happened last time? I give you the flat price before I start, and if I find something else, I stop and show you photos before doing more.”"],["“Why do you need a deposit for the re-pipe?”","“The deposit covers the pipe and fittings so they’re on site on day one. What payment schedule works for you? It’s in the contract, and the balance is due after the inspection passes and you’ve checked the work.”"]],faq:[["Can I start with just service and repairs?","Yes, if your license allows it. Clogs, toilets, faucets and leaks need little equipment and build reviews fast. Add water heaters, re-pipes and sewer work once your price book and insurance are solid."],["Do I need a master license if I work alone?","In most licensing states, running a plumbing business and pulling permits takes a master or contractor license (or a master on record), even if you work alone. A journeyman license usually lets you work under someone else. Check your state board."],["How do I get paid?","Service calls are usually paid on the spot by card. Bigger jobs like re-pipes and sewer lines often take a deposit, with the balance after inspection. Property managers may want net-30 terms, so agree on them in writing. Check your state’s limits on deposits."],["Should I offer 24/7 emergency service?","It pays well and wins loyal customers, but it can wear you out and pull you off booked jobs. Many new plumbers start with extended hours and an after-hours rate, then add true 24/7 cover once they have a second plumber."],["How do I compete with big plumbing companies?","Answer the phone, give a flat price before you start and leave the place clean. Franchises outspend you on ads, but a small plumber who shows up on time and texts photos earns reviews and repeat landlord work."]],tools:["Quoting and invoicing: Housecall Pro, Jobber or ServiceTitan, or a simple spreadsheet to start.","Pricing and inspection: a flat-rate price book (build your own or use one such as Profit Rhino) and a sewer camera with a locator (such as RIDGID SeeSnake) so customers can see the problem.","Reviews: a Google Business Profile with a short review link you text after every job.","Scheduling: a shared calendar with an on-call rota, plus an answering service so after-hours calls don’t go to voicemail."]},
painting:{lic:["Rules vary a lot by state. Some states license painters: California (a C-33 license for jobs of $1,000 or more, labor and materials), Oregon (a Construction Contractors Board license for any paid painting) and Arizona, for example. Others, such as Texas, have no state license for painters, though cities may require registration. Confirm with your state licensing board.","Where a license is required, expect to show experience or take training, pass an exam, and carry a bond and insurance. California asks for four years at journey level and two exams, and Oregon asks for 16 hours of pre-license training and an exam. This can take weeks or months, so start early.","Most residential painting needs no permit, but scaffolding over sidewalks, some commercial jobs and HOA color rules can need approval, so confirm the homeowner has it. Some cities require solicitation permits for door-to-door sales, so check before you canvass.","EPA’s lead rule (RRP) covers most paid work that disturbs paint in homes built before 1978: more than 6 sq ft inside or 20 sq ft outside. Your business needs EPA firm certification, a certified renovator must direct the work, and you must give the owner the Renovate Right pamphlet before you start. Many new painters don’t know the firm certification is separate, and the fines are steep.","Once you hire, OSHA rules for ladders, scaffolds and respirators apply (spraying and sanding often need a respirator program). Never rinse brushes or dump wash water into a storm drain, and dispose of oil-based paint and solvents the way your area requires."],cost:[["Business setup (LLC, license where required, bond)","$100–$1,500"],["General liability insurance","$500–$2,500 per year"],["Workers’ compensation","Depends on payroll and state; painting rates are high, so price it before your first hire"],["EPA lead-safe certification (firm and renovator), respirators, lead-safe supplies","$700–$1,800"],["Ladders, planks, brushes, rollers, drop cloths, airless sprayer","$1,000–$6,000"],["Used van or pickup","$5,000–$20,000 if you don’t already own one"],["Software, website, marketing","$300–$2,000"],["Working capital for paint and supplies until customers pay","$500–$3,000"]],costnote:"Bare minimum (you own a vehicle, work solo on interior rooms with brushes and rollers, and take the lead-safe course) is roughly $2,500–$5,000. A crew-ready start with an airless sprayer, ladders and planks, workers’ comp and a used van is closer to $15,000–$35,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, get insurance quotes and confirm licensing. Book the EPA lead-safe renovator course and apply for firm certification, since approval can take weeks. Open a pro account at a paint store."],["Weeks 3–4","Build a price sheet per square foot of wall, ceiling and siding, with add-ons for trim, doors and repairs. Set up a Google Business Profile, a one-page site and a quote template with a written prep plan. Photograph every room before and after."],["Month 2","Paint 5–10 single rooms, accent walls and rental turnovers for friends, neighbors and landlords. Ask each customer for a review and a referral. Introduce yourself to 10 realtors and property managers."],["Month 3","Start quoting whole-house interiors and, in season, exteriors. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Painters price by the square foot of surface painted (wall area, not floor area), with ceilings, trim and doors added separately. Example: the main living areas of a 3-bedroom home, about 1,800 sq ft of wall, two coats. If labor and paint cost you about $0.90 per sq ft (roughly $0.60 of labor and $0.30 of paint), that’s $1,620, plus about $150 for patching compound, caulk, tape and plastic. That’s $1,770. Add 30–40% for overhead and profit and the quote lands around $2,300–$2,480. Itemize prep, number of coats, paint brand and sheen, colors, which walls, ceilings and trim are included, and furniture moving. Your own costs will differ, so treat this as an example.",mistakes:["Buying paint for a big exterior on your own card and waiting weeks to be paid. Take a deposit that covers materials, and bill the balance at the final walk-through.","Working without cover for property damage and overspray. One spilled gallon on a carpet or overspray on a neighbor’s car can cost more than the job paid.","Quoting “paint the living room” with no written scope. List the walls, ceilings, trim, doors, number of coats, colors and sheen, and who moves the furniture.","Underpricing prep. Peeling paint, rotten trim and failed caulk eat hours, so price prep on its own line and add a clause for wood repair found while scraping, priced per linear foot.","Sanding or scraping pre-1978 paint without EPA lead-safe certification and the Renovate Right pamphlet. The fines are steep, and lead dust can harm children.","Letting quotes go cold. People compare painters for weeks, and the painter who follows up with photos of similar jobs often gets the work."],obj:[["“Another painter quoted a lot less.”","“That’s fair, I’d compare too. How many coats, what paint and how much prep is in their quote? That’s where painting prices differ. I’ll send you photos of a two-year-old job of mine so you can see how the prep holds up.”"],["“I’m getting a few more quotes.”","“Good idea. What matters most to you, the finish or the timeline? Ask each painter the same things: paint brand and line, number of coats, what prep they do, and whether they’re lead-safe certified if your home is from before 1978. I’ll check in Tuesday.”"],["“I need to check the colors with my partner.”","“Of course, colors are a shared decision. Which rooms are you still unsure about? I’ll bring a few large color samples to try on the wall and a one-page summary so you can decide together.”"],["“Can you knock something off?”","“I can trim the scope to fit a budget, like one coat on walls staying the same color, or ceilings later. What number did you have in mind? I won’t skip prep, because that’s what keeps paint from peeling.”"],["“We’ll just paint it ourselves.”","“Plenty of people do. Which part are you dreading most? Many customers paint the easy walls and hire out ceilings, stairwells and trim. I can quote just those parts.”"],["“Let’s wait until next spring.”","“That can work. Have you noticed peeling or bare wood yet? Once wood is exposed, water gets in, and next year’s job can include rot repair. I can spot-prime the worst areas now and book you early for spring.”"],["“Will you finish on time, and will my house be a mess?”","“Fair question, painters get that a lot. What’s your deadline? I’ll give you a written schedule, cover floors and furniture, and clean up every day. Here are three recent customers you can call.”"],["“Why do you want a deposit?”","“It pays for your paint and supplies, which I order in your colors. How would you like to pay? It’s in the contract, and the balance is due after we walk through the job together and you’re happy.”"]],faq:[["Can I start with just interior rooms?","Yes. Interiors need less equipment, work in any weather and build reviews fast. Add exteriors once you have ladders, planks, a sprayer and insurance that covers work at height."],["Do I need lead-safe certification if I work alone?","Yes, if you’re paid to disturb more than the small-area limits of paint in homes or child-care facilities built before 1978. The rule covers your business and the person doing the work, not just crews. Some states run their own program, so check yours."],["How do I get paid?","A common structure is a deposit for paint and supplies, then the balance at the final walk-through. For big exteriors, add a progress payment when prep is done. Check your state’s limits on deposits."],["Should I take work from builders and general contractors?","It can fill your calendar, but margins are thin, schedules slip, and you may wait 30–60 days or longer to be paid. If you do, get payment terms in writing, learn your state’s lien rules, and keep homeowners as your main customers."],["How do I compete with big painting companies?","Be the owner who shows up. Franchises have brand names, but you can win with a written prep plan, quick quotes, daily cleanup and photos of past jobs."]],tools:["Quoting and invoicing: PaintScout, Jobber or Housecall Pro, or a simple spreadsheet to start.","Measuring: a laser distance measurer (such as Bosch or Leica Disto) for walls, and Hover for exterior siding areas.","Reviews: a Google Business Profile with a short review link you text after every job, plus before and after photos.","Scheduling: a shared calendar and a weather app that shows rain, temperature and dew point, so you can move exterior days early."]},
handyman:{lic:["Rules vary a lot by state. California and Arizona, for example, let you work without a contractor license only on jobs under $1,000 (labor and materials) that need no permit, and California adds that you can’t hire anyone for the job. Texas has no state handyman or general contractor license, though cities may require registration. Confirm with your state licensing board.","If you outgrow the limit, a contractor license usually means documented experience, an exam, a bond and insurance. California, for example, asks for four years at journey level. This can take weeks or months, so start early.","Electrical, plumbing, gas and HVAC work needs a trade license in most states, even for small jobs, and permitted work often needs a contractor license. Some states (Arizona and California, for example) require unlicensed handymen to say they’re not licensed in every ad, and cities may require a business license.","Don’t split one job into small invoices to stay under the limit. Regulators treat it as one project, and in states like California that counts as unlicensed contracting, with fines. If the total is over the limit, refer it to a licensed contractor.","A helper you direct is usually an employee, not a 1099 contractor, so plan for payroll and workers’ comp before you hire. In homes built before 1978, EPA’s lead rule also applies to repairs that disturb paint, such as cutting drywall or replacing a window."],cost:[["Business setup (LLC, city business license)","$100–$800"],["General liability insurance","$600–$1,500 per year"],["Business auto cover (personal policies may exclude work use)","$500–$3,000 per year; ask your agent"],["Safety gear and EPA lead-safe renovator training","$300–$800"],["Hand and power tools (drill and driver kit, oscillating tool, miter saw, ladders)","$1,000–$5,000"],["Used pickup or small van with racks","$5,000–$20,000 if you don’t already own one"],["Software, website, marketing","$300–$1,500"],["Working capital for materials until customers pay","$300–$2,000"]],costnote:"Bare minimum (you own a vehicle and most tools, and work solo on small jobs under your state’s limit) is roughly $2,000–$4,000. A fully equipped start with a used work van, a full tool kit and a part-time helper is closer to $15,000–$30,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Learn your state’s handyman limit and which trades need a license, register the LLC, get your EIN and bank account, and get liability and business auto quotes. Write down the jobs you will and won’t take."],["Weeks 3–4","Build a service menu with an hourly rate, a minimum and flat prices for 15 common jobs (TV mounting, door adjustments, drywall patches). Set up a Google Business Profile, a one-page site and card payments on your phone."],["Month 2","Do 15–25 small jobs for neighbors, friends and Nextdoor contacts. Ask each customer for a review and whether they have a longer list. Introduce yourself to 10 realtors and property managers."],["Month 3","Start quoting full inspection repair lists, rental turnovers and half-day or full-day bookings. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Handymen sell time: an hourly rate with a minimum, turned into a flat quote for a list of tasks. Example: a realtor’s inspection repair list (re-hang two doors, patch four drywall holes, re-caulk a tub, re-secure a loose handrail, fix a sticking gate). You estimate 7 hours on site plus 1 hour for the supply run, so 8 hours. If your labor costs you $45 an hour (your pay, taxes and insurance), that’s $360, plus about $160 in materials. That’s $520. Add 40–50% for overhead and profit (vehicle, tools, unpaid drive time) and the quote lands around $730–$780. In California or Arizona, a total like this stays under the $1,000 limit only if no permit is needed (and in California, no helper). Itemize each task, the materials, and what’s extra if you find rot or damage behind a wall. Your own costs will differ, so treat this as an example.",mistakes:["Buying materials for every job on your own card and invoicing later. Collect payment on completion, and ask for materials money upfront on bigger lists.","Skipping liability or business auto cover. A cracked tile, a flooded bathroom or a crash on the way to a job can cost more than a year of premiums.","Saying “sure, I’ll look at that too” with no written scope. Agree on the task list and price before you start, and quote add-ons separately.","Pricing only the hours on site. Drive time, supply runs and estimates go unpaid unless you build them in, so use a minimum charge and a trip fee for far-out jobs.","Taking electrical, plumbing or permitted work, or splitting a job to stay under the limit. It can void your insurance and bring fines.","Letting quotes for bigger lists go cold. Homeowners juggle many small jobs and forget, so a friendly text at 2 and 5 days wins work."],obj:[["“The guy on Nextdoor charges less.”","“That’s fair, there’s always someone cheaper. Does he carry insurance and come back if something isn’t right? I do both, and I show up when I say I will. Want me to send proof of insurance with the quote?”"],["“I’ll get a couple more quotes.”","“Sure. Are you comparing by the hour or for the whole list? Check whether each price covers the full list, what’s included in materials, and whether they’re insured. I’ll text you Wednesday in case questions come up.”"],["“I need to check with my spouse.”","“Of course. Which items matter most to them? I’ll text you the list with a price for each item so you can choose together, and you can drop anything.”"],["“Can you just charge me for the time you’re here?”","“I understand, nobody likes paying for drive time. How many other things are on your list? My minimum covers travel, tools and insurance, so the best value is giving me several jobs in one visit.”"],["“I’ll watch a video and do it myself.”","“Lots of jobs are DIY friendly. Which part feels risky to you? I can do just the tricky part, like hanging a heavy mirror into studs, and leave the rest to you.”"],["“It’s not urgent, maybe next month.”","“No problem. Is anything on the list a safety or water issue, like a loose railing or failing caulk? Those get worse fast. I can do those now and book the rest when you’re ready.”"],["“I’m not comfortable having a stranger in my house.”","“That’s a fair concern. What would make you comfortable? I can send my insurance, reviews and a photo of who’s coming, and text you when I’m on the way.”"],["“Can I pay you next week?”","“I understand. What payment method is easiest for you today? I take cards on my phone, so we can settle up after you’ve checked the work and before I leave. For bigger lists, I take a materials deposit upfront.”"]],faq:[["Can I start with just small jobs like mounting and minor repairs?","Yes. Small jobs build reviews, cash and a list of repeat customers with little risk. Move to full repair lists and day bookings once you know how long tasks really take."],["Do I need a license if I work alone?","It depends on your state and the job. Many states cap unlicensed work by job size or require a license for permitted work, and electrical, plumbing and gas work need a trade license regardless. Working alone doesn’t change that, so check your state board."],["How do I get paid?","Most handymen collect on completion by card or payment app. For bigger lists, take a materials deposit. Property managers may want monthly invoices, so agree on terms in writing. Check your state’s limits on deposits."],["Should I use Thumbtack, Angi or TaskRabbit?","They can fill early gaps, but lead and platform fees add up, and you compete mostly on price. Use them to get started, ask every customer for a direct review and referral, and shift to your own Google profile and repeat clients."],["How do I compete with big handyman companies?","Be reliable and easy to book. Franchises and apps have brand names, but a handyman who answers fast, shows up on time, tidies up and takes the whole list in one visit gets the repeat calls."]],tools:["Quoting and invoicing: Jobber, Housecall Pro or Square Invoices, or a simple spreadsheet to start.","Estimating: a service menu with flat prices, plus a time tracker (such as Toggl or the job timer in Jobber) to log how long each task really takes.","Reviews: a Google Business Profile with a short review link you text after every job, plus a Nextdoor business page.","Scheduling: a shared calendar and a route planner (Google Maps with multiple stops) so you can group jobs by area."]},
landscaping:{lic:["Rules vary a lot by state. Routine mowing and maintenance usually needs only a local business license. Some states license landscape installation work: California requires a C-27 license for jobs of $1,000 or more, and Nevada and Oregon also license landscape contractors. Others (Texas, for example) have no general state landscaping license but require a state license to install irrigation. Confirm with your state licensing board.","Where a contractor license is needed, expect to show about four years of experience, pass trade and law exams and post a bond (California’s is $25,000). Spraying weed killer or insect control for pay usually needs a separate state pesticide applicator license, with a core exam, a turf and ornamental exam and continuing education to renew. This can take weeks or months, so start early.","Retaining walls, drainage work and irrigation often need a local permit, and you must call 811 a few days before you dig. Many cities limit gas leaf blowers or noise hours, and some require a solicitor permit for door-to-door sales. Door hangers are fine, but putting flyers in mailboxes breaks federal law.","The trap is spraying without a license. Weed-and-feed and weed killer from the hardware store count as pesticides once you apply them for pay, and in most states that needs a license even if you work alone. Fertilizer alone often doesn’t. Until you’re certified, sell mowing and mulch and refer spraying to a licensed applicator.","OSHA rules apply once you have employees. Train your crew on mowing slopes, thrown debris and trimmer kickback, and supply hearing and eye protection. Plan water, shade and breaks for heat, because some states (California, Washington and Oregon, for example) have their own outdoor heat rules. Many cities also ban blowing clippings into streets or storm drains."],cost:[["Business setup (LLC, business license, contractor license if needed)","$150–$1,500"],["General liability insurance","$400–$1,000 per year"],["Commercial auto, equipment cover and workers’ comp","Auto often $1,200–$3,000 per year; comp depends on payroll and state"],["Safety gear and pesticide applicator license (if you spray)","$200–$700"],["Mowers, trimmer, blower, edger, hand tools","$2,500–$15,000 (a commercial zero-turn alone is often $8,000–$14,000 new)"],["Used truck and trailer","$1,500–$8,000 for a trailer; $10,000–$25,000 for a truck if you don’t already own one"],["Software, website, marketing","$300–$1,500"],["Working capital for fuel, repairs, mulch and plants until customers pay","$1,000–$3,000"]],costnote:"Bare minimum (you own a truck, work solo with a used walk-behind mower, trimmer and blower and an open trailer, mowing and cleanups only) is roughly $4,000–$8,000. A crew-ready start (a used truck, a commercial zero-turn, an enclosed trailer and one helper on payroll) is closer to $35,000–$55,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account and get quotes for liability, commercial auto and equipment cover. Check whether your state licenses installs or irrigation, and decide whether to start studying for the pesticide applicator exam."],["Weeks 3–4","Set up a Google Business Profile, a one-page site and a per-visit price sheet. Buy or tune up your mower, trimmer and blower, and pick two or three neighborhoods within 10 minutes of each other. Photograph every lawn before and after."],["Month 2","Do 5–10 one-time cleanups and overgrown mows for neighbors and friends, and sign your first 10–15 weekly clients. After each visit, hang 20–30 door hangers on the same street. Introduce yourself to 5 local realtors and 5 property managers who need curb appeal."],["Month 3","Offer mulch, bed edging and aeration to every weekly client, then start quoting small installs. Follow up on every quote within 48 hours and again at 5 days. Check which streets and lead sources paid off, and drop stops that sit far off your route."]],price:"Landscapers price maintenance per visit: one mow, trim, edge and blow. Example: a quarter-acre lot takes one person about 40 minutes on site plus 10 minutes of driving to the next stop. If labor, fuel and equipment wear cost you about $34 per visit, a 30-visit season (April to October) is $1,020, plus about $60 in yard-waste fees for the bagged spring and fall cuts, so $1,080. Add 25–35% for overhead and profit and the season lands around $1,350–$1,460. That’s about $45–$49 a visit, or roughly $193–$208 a month if you bill over seven months. Itemize mowing, trimming, edging, blowing, bagging and any catch-up cuts or cleanups. Your own costs will differ, so treat this as an example.",mistakes:["Spending summer income as if it lasts all year. Set aside part of every summer payment, or line up winter work, to cover the slow months.","Leaving mowers on an open trailer with no equipment cover. Trailer theft is common, and general liability doesn’t pay for your own gear. Add equipment (inland marine) cover and lock the trailer.","Starting weekly service with no written agreement. Spell out what a visit includes, how rain days and skipped weeks work, and 30 days’ notice to cancel, so clients don’t quietly drop you in the July dry spell.","Underpricing the first visit and far-off stops. Charge a one-time catch-up fee when grass is over 6 inches, and add a drive-time charge for lawns off your route.","Spraying weed killer without an applicator license, or stuffing flyers in mailboxes. Either one can bring fines that wipe out a season’s profit.","Letting cleanup and install quotes go cold. Spring buyers book whoever gets back to them first, and many sales happen on the second or third contact."],obj:[["“The other guy charges less per cut.”","“That’s fair, I’d compare too. Does his price include edging, trimming and blowing off the drive, and is he insured if a rock breaks a window? That’s where prices differ. I’ll put exactly what each visit includes in writing so you can compare line by line.”"],["“I want to get a few more quotes.”","“Makes sense. Which matters most to you: price, a set day or clean edges every time? When you compare, check how often they come, what a visit includes, how they handle rain days and whether they’re insured. I’ll check back Friday in case anything’s unclear.”"],["“I need to check with my partner first.”","“Of course. What do you think they’ll ask about, the price or the schedule? I’ll text you a one-page summary with the visit checklist and before photos so you can look at it together.”"],["“Can you do it for less?”","“I can, by changing the plan. What budget did you have in mind? Every-other-week mowing or skipping edging on the back lawn brings it down. I won’t rush the cut, because scalping the grass costs you more to fix later.”"],["“My neighbor’s kid will do it for $25.”","“That can work, and I’d never knock a kid earning money. What happens when they’re away or it rains for a week in May? I’m insured, I come on a set day and I text before each visit. Want me to do one cut so you can compare?”"],["“Let’s wait until the lawn really needs it.”","“Understood. How tall is it now? In spring grass can grow an inch or more a week, and a lawn that gets ahead of you needs a catch-up cut that costs more. I can start every other week and switch to weekly when it takes off.”"],["“The last guy just stopped showing up.”","“That’s frustrating, and it happens a lot. What day of the week works best for you? I put your day in writing, text before every visit and send a photo when I’m done. If rain pushes me back, you hear it from me first.”"],["“Why do you want a card on file?”","“Fair question. Would you rather not deal with checks? You’re billed once a month for visits already done, and every charge comes with an emailed invoice listing the dates. I’ll send you a sample invoice first so you can see it.”"]],faq:[["Can I start with just mowing?","Yes. Mowing and one-time cleanups build a route, reviews and cash with little risk. Add mulch, edging and small installs once your weekly route is full, and check whether your state needs a license for install work."],["Do I need a license to kill weeds if I work alone?","Pulling weeds by hand, no. Spraying them for pay, in most states yes, even with store-bought products and even if you work alone. Fertilizer alone often doesn’t need one, but weed-and-feed does. Check with your state department of agriculture."],["How do I get paid?","Most weekly clients pay monthly for visits already done, by card on file or autopay. For installs, a deposit for mulch and plants and the balance on completion is common. Check your state’s limits on deposits. California, for example, caps them at 10% or $1,000, whichever is less."],["Should I take tree work?","Be careful. Tree removal pays well, but it’s among the most dangerous work there is, and many landscaping policies exclude it. Stick to shrubs and small trees you can prune from the ground, and refer big trees to a certified arborist who may send work back your way."],["How do I compete with big landscaping companies?","Be the same face on the same day every week. Big companies rotate crews and add fees. Small owners win with dense routes, quick replies, a photo after every visit and strong reviews on a few streets."]],tools:["Quoting and invoicing: Jobber, Yardbook or LMN, or a simple spreadsheet to start.","Measuring: satellite lot measurements (such as Go iLawn or Deep Lawn) or the measure tool in Google Earth, so you can quote without a site visit.","Reviews: a Google Business Profile with a short review link you text after every visit, plus a before-and-after photo.","Scheduling: route planning in your job app or Google Maps to keep stops close, and a weather app so you can move rain days early."]},
'junk-removal':{lic:["Rules vary a lot by state and city. Most states (Texas and Florida, for example) have no state junk removal license, though cities and counties may require a hauler permit. Some states regulate anyone who hauls other people’s waste: New Jersey requires an A-901 license and DEP registration, and Pennsylvania requires waste transportation authorization for trucks over 17,000 lb and trailers over 10,000 lb that deliver to its disposal sites. Confirm with your state environmental agency and your city.","Where a hauler license is required, expect background checks, proof of insurance, fees and a decal for each vehicle. New Jersey’s A-901 includes an integrity review by the State Police and the Attorney General’s office, while Pennsylvania’s authorization takes about 15 days once the application is complete. If your truck, or truck and trailer, is rated 10,001 lb or more and crosses state lines, you also need a USDOT number. This can take weeks or months, so start early.","Some cities give exclusive franchises for hauling trash, so check whether junk removal is allowed there before you advertise. Tearing down a shed or deck may need a demolition permit, and in some states a contractor license (California requires one for jobs of $1,000 or more). Some towns also require a solicitor permit for door-to-door sales.","The trap is where the junk ends up. Leaving it in someone else’s dumpster, a vacant lot or a roadside is illegal dumping, and items can be traced back to you and your customer. Fridges, freezers and window AC units must have their refrigerant properly recovered before disposal, and scrap yards and landfills ask for a signed statement that it was done. Keep every scale ticket and receipt.","OSHA rules apply once you have employees: safe lifting, gloves, eye protection and puncture-resistant boots. Treat popcorn ceilings, old pipe wrap, vermiculite and old floor tiles as possible asbestos and leave them alone. Tarp and tie down every load, because unsecured loads are against the law nearly everywhere."],cost:[["Business setup (LLC, business license, hauler permit)","$150–$1,500, more where a state hauler license applies"],["General liability insurance","$700–$2,000 per year"],["Commercial auto, plus workers’ comp once you hire","Auto often $2,000–$6,000 per year; comp depends on payroll and state"],["Safety gear (gloves, boots, eye protection, respirators, first-aid kit)","$200–$500"],["Dollies, appliance dolly, straps, tarps, saw, rakes and shovels","$500–$1,500"],["Utility or dump trailer, or a used junk truck","$2,000–$12,000 for a trailer; $20,000–$45,000 for a truck, if you don’t already own one"],["Software, website, marketing, truck lettering","$500–$2,500"],["Working capital for dump fees, fuel and helper pay until customers pay","$1,000–$3,000"]],costnote:"Bare minimum (you own a pickup, buy a used high-sided utility trailer and work solo on single items and small loads) is roughly $4,000–$8,000. A crew-ready start (a used 15-cubic-yard junk truck, one helper on payroll and full clean-outs) is closer to $30,000–$60,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account and get liability and commercial auto quotes. Check state and city hauling rules, and visit your nearest transfer station, landfill and recycling center to learn their fees, hours and what they refuse."],["Weeks 3–4","Set up a Google Business Profile with photos of your truck, a one-page site and a price sheet by load size. Line up a donation center that takes furniture and an appliance recycler. Letter the truck with your name and phone number."],["Month 2","Do 10–15 single-item pickups and small loads (a couch, a fridge, a corner of a garage) for neighbors and local groups. Take before-and-after photos and ask every customer for a review. Introduce yourself to 10 realtors, property managers and estate attorneys."],["Month 3","Start quoting full clean-outs (garages, basements, estates) from walkthroughs or photo sets. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off, and compare each job’s dump fees to what you charged."]],price:"Junk removers price by how much of the truck a load fills, usually in eighths of a truck of known size. Example: a garage clean-out fills about half of a 15-cubic-yard truck, so 7.5 cubic yards. If labor, fuel and truck costs run you about $30 per cubic yard, that’s $225. Add about $100 in dump fees (roughly 1.25 tons at $80 a ton) and $45 in item fees for a mattress and a fridge, and your cost is $370. Junk jobs are short, so overhead per job is high: add 35–50% for overhead and profit and the quote lands around $500–$555. Itemize the load size, labor, disposal, item fees (mattresses, tires, appliances) and any stairs or long carries. Your own costs will differ, so treat this as an example.",mistakes:["Taking net-30 terms from property managers with no cushion. You pay dump fees and helper wages the same week, so invoice the day you finish and keep a month of costs in the bank.","Hauling on a personal auto policy. A claim from an accident with a loaded truck or trailer can be denied, so get commercial auto before your first paid load.","Quoting from a phone call alone. Customers forget the basement freezer or the pile behind the shed. Quote from photos or a walkthrough, and put in writing that extra items are priced per eighth of a truck.","Pricing heavy loads by volume alone. Half a truck of concrete, dirt or shingles can weigh several tons and cost more to dump than you charged. Set a weight limit per load and a per-ton charge above it.","Taking paint, chemicals, tires or old TVs without knowing where they can go. Many landfills refuse them or charge extra, and some states ban electronics from the trash. Keep a “won’t take” list and a list of drop-off sites.","Letting clean-out quotes go cold. Estates and move-outs run on deadlines, and the hauler who calls back first usually wins the job."],obj:[["“The franchise down the road quoted less.”","“Could be, and it’s worth comparing. Was theirs a firm price or an estimate that changes once it’s on the truck? Check whether it includes loading from inside, sweeping up and dump fees. I give a firm price before we load, and I’ll put it in writing so you can set it next to theirs.”"],["“I want a couple more quotes first.”","“Of course. Will they quote from photos or come out? Make sure each one includes loading, disposal and item fees, because that’s where totals change. I can hold Thursday morning for you until Wednesday night.”"],["“I need to check with my siblings, it’s Mom’s house.”","“Of course, that’s a lot to decide together. Is there anything they’ll want to keep or donate? I’ll send photos of each room with a price, and set aside anything you mark so nobody’s surprised.”"],["“Can you knock something off?”","“Maybe. What number did you have in mind? If you bring things to the garage or driveway, or we come on a day I’m already nearby, I can lower it. I won’t skimp on the dump fees, because that’s what keeps your things out of a ditch with your name on them.”"],["“I’ll just rent a dumpster.”","“That works for some projects. How much of it are you planning to load yourself? A dumpster can need a street permit, sits in your driveway for days and has weight limits and banned items. We load everything in one visit and sweep up. Want both prices side by side?”"],["“I’ll deal with it after the holidays.”","“Understood. Is there a date it has to be gone by, like a closing or a move-out? End-of-month dates fill fast, and a full garage only gets fuller. I can take the heavy pieces now and come back for the rest when you’re ready.”"],["“How do I know you won’t dump it in the woods?”","“Good question to ask, because illegal dumping can be traced back to you. Is there anything you’d like donated or recycled? I’ll text you the dump receipt and any donation receipt after the job.”"],["“Do I pay before or after you load?”","“After, and that’s a fair thing to ask. We confirm the final price once it’s on the truck and before we leave, so you see what you’re paying for. Is this a one-day job or a bigger clean-out? For jobs that take more than a day, I ask for a deposit to cover the first dump runs, and it’s all on the written quote.”"]],faq:[["Can I start with just a pickup and a trailer?","Yes. Single items and small loads build reviews and cash with little risk. Move to a bigger truck once you’re turning away full clean-outs, not before."],["Do I need a hauling permit if I only use a trailer?","Sometimes. Some states and cities regulate anyone hauling other people’s waste whatever the vehicle size, and others only regulate larger trucks. Ask your city clerk and state environmental agency before your first paid load."],["How do I get paid?","Most homeowners pay on the spot by card once the load is on the truck. For multi-day clean-outs, a deposit covering the first dump runs and the balance on completion is common. Property managers often pay on invoice within 30 days. Check your state’s limits on deposits."],["Should I add light demolition, like sheds and hot tubs?","It can pay well, but it’s riskier. Hot tubs and sheds may have live wiring, demolition can need a permit, and some states require a contractor license above a dollar limit. The debris is heavy, so price it by weight. Start with free-standing items and learn the rules first."],["How do I compete with big junk removal franchises?","Be faster and more personal. Franchises run on call centers and booking windows. Small haulers win with same-day or next-day slots, firm prices from photos, receipts for donations and dump runs, and the owner on the job."]],tools:["Quoting and invoicing: Jobber, Housecall Pro or Workiz, or a simple spreadsheet to start.","Estimating: photo and video quotes by text, checked against a load chart for your truck marked in eighths, with before-and-after photos saved in an app such as CompanyCam.","Reviews: a Google Business Profile with a short review link you text after every job.","Scheduling: a shared calendar with dump runs built into each slot, and Earth911’s recycling search to find drop-off sites for paint, electronics and batteries."]},
'hauling-transportation':{lic:["Rules vary a lot by state. Some states license local (intrastate) movers: California requires a permit from the Bureau of Household Goods and Services, and Texas requires TxDMV registration and cargo insurance for household goods carriers whatever the truck size. Others (Maryland, for example) don’t license movers but still set rules for local moves. Any move that crosses a state line needs a USDOT number and FMCSA household goods authority. Confirm with the agency that licenses movers in your state.","Where a permit is required, expect to file proof of liability, cargo and workers’ comp insurance, pass a background check and pay fees. Interstate authority adds federal insurance filings, a process agent and a written tariff of your rates. This can take weeks or months, so start early.","Many cities require a parking or loading permit for a truck on the street, and many buildings want a certificate of insurance before you can use the elevator. Several states require a written estimate before the move and set rules for binding and not-to-exceed prices. Interstate movers must show their USDOT number in ads, and some states require your state permit number too.","The trap is the state line. A 15-mile move from one state into another is an interstate move, and doing it without FMCSA authority is illegal however short the trip. On interstate moves you also can’t demand more than 110% of a non-binding estimate at delivery to release the goods. On any move, never hold belongings until the customer pays more.","Your helpers are almost always employees, not contractors, because they work your jobs on your schedule with your equipment. That means payroll taxes and workers’ comp. If a truck rated 10,001 lb or more crosses state lines, drivers need a DOT medical card and you follow hours-of-service rules. A CDL is needed only for trucks rated 26,001 lb or more."],cost:[["Business setup (LLC, state mover permit or registration)","$300–$2,000"],["General liability insurance","$1,000–$2,500 per year"],["Commercial auto, cargo and workers’ comp","Auto often $5,000–$12,000 per truck per year and cargo $1,000–$2,000; comp depends on payroll and state and is often the biggest cost once you hire"],["Safety and protection gear (gloves, boots, floor runners, door jamb pads)","$300–$800"],["Dollies, moving pads, straps, shrink wrap, tool kit","$800–$3,000"],["Used 16–26-foot box truck with a ramp or liftgate","$20,000–$45,000 if you don’t already own one; labor-only moves need none"],["Software, website, marketing","$500–$2,500"],["Working capital for helper payroll, fuel and supplies until customers pay","$1,500–$5,000"]],costnote:"Bare minimum (labor-only moves with no truck, you plus one helper, loading and unloading customers’ rental trucks and containers) is roughly $3,000–$7,000. A crew-ready start (a used box truck, a crew of three on payroll, full local moves) is closer to $35,000–$70,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN and open the bank account. Check your state’s mover permit, then get quotes for liability, cargo, commercial auto and workers’ comp. Set up payroll for helpers before anyone works a job."],["Weeks 3–4","Set up a Google Business Profile, a one-page site and an hourly rate card with your minimum and travel fee. Buy pads, dollies and straps, list your crew on HireAHelper or U-Haul’s Moving Help for labor-only jobs, and line up two reliable helpers you can call on short notice."],["Month 2","Do 8–12 labor-only loads and unloads and small apartment moves. Photograph how you pad and wrap furniture, and ask every customer for a review. Introduce yourself to 10 realtors, apartment managers and senior living communities."],["Month 3","Start quoting full local moves with your own truck or a commercial truck rental, using video walkthroughs. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off, and book end-of-month dates early."]],price:"Movers price local moves by the crew-hour: a set number of movers plus a truck, with a minimum. Example: a two-bedroom apartment move takes three movers about 5 hours, plus 1 hour of travel. If wages, payroll taxes, workers’ comp, fuel and truck costs run you about $110 per crew-hour, 6 hours is $660, plus about $40 for shrink wrap, tape and mattress bags, so $700. Add 30–40% for overhead and profit and the move lands around $910–$980, which works out to about $152–$163 per crew-hour. Itemize the crew size, hourly rate, minimum, travel time, materials and any stairs, long carries or heavy items. Your own costs will differ, so treat this as an example.",mistakes:["Paying helpers in cash out of the day’s takings. When a card payment is held or disputed, payroll is still due. Keep at least two weeks of payroll in the bank and run it through a payroll service.","Assuming general liability covers customers’ belongings. It usually excludes property in your care, so one dropped TV or scratched piano isn’t covered without cargo or bailee coverage.","Quoting without an inventory. A storage unit nobody mentioned, a sleeper sofa or a third-floor walk-up can double the hours. Quote from a video walkthrough, list what’s included, and price extra items and access problems in writing.","Quoting flat prices too low before you know your crew’s pace. Price by the hour with a minimum at first, and add set fees for stairs, long carries and pianos or safes.","Taking a move across a state line without FMCSA authority, or advertising without the permit and USDOT numbers your state and FMCSA require. Both invite fines and complaints.","Letting quotes go cold. People book a mover within days of their first call, so the one who follows up first and holds the date in writing usually wins."],obj:[["“Another company quoted me $400 less.”","“That’s worth a look. Is theirs a binding price or an estimate that can grow on moving day? Check the crew size, the rate after the minimum, travel time and what happens if something breaks. I’ll send my quote with all of that spelled out so you can compare line by line.”"],["“I’m still collecting quotes.”","“Smart, especially for a move. Did the others see your place, or guess from the number of bedrooms? Quotes from a video walkthrough are closer to the real bill. End-of-month dates book up fast, so I can hold yours until Friday at no charge.”"],["“Let me talk it over with my spouse.”","“Of course. What will they want to know, the total, the timing or how we handle fragile things? I’ll send a one-page summary with the crew, the hours and how we wrap furniture so you can decide together.”"],["“Is there any way to bring the price down?”","“Usually, yes. What budget are you working with? Packing boxes yourself, taking beds apart before we arrive or picking a weekday mid-month all cut the hours. I won’t send fewer movers than the job needs, because that’s how things get dropped.”"],["“I’ll just rent a truck and get friends to help.”","“That works for a lot of people. How many friends can you count on for a full Saturday, and who’s carrying the sofa down three flights? We also do labor-only: you rent the truck and we load and unload it, which costs less than a full move. Want a quote for both?”"],["“I’ll book closer to the date.”","“Understood. When is your lease up? Weekends and the last few days of the month fill weeks ahead, and if your date goes, what’s left is a weekday or a rush price. I’ll pencil you in now and confirm the details the week before.”"],["“How do I know you won’t hold my stuff hostage?”","“Good question, because some movers do. Have you had a bad move before? You get a written estimate before the move, and the bill is based on the hours on the clock. Here’s my permit number, my insurance certificate and reviews you can check before you book.”"],["“Why do you need a deposit just to book?”","“Fair question. Has a mover ever not shown up on you? The deposit holds your date and crew so I don’t give them to someone else. It comes off your final bill, the refund policy is on the estimate, and you pay the rest once everything’s in your new place and you’ve checked it over.”"]],faq:[["Can I start with just labor-only moves?","Yes. Loading and unloading customers’ rental trucks, containers and storage units needs no truck and builds reviews fast. Move to full moves once your crew is steady and your insurance covers transport. Check whether your state’s mover permit covers labor-only work too."],["Do I need a CDL or a USDOT number for a box truck?","A CDL only if the truck is rated 26,001 lb or more, which is why many box trucks are rated just under it. A USDOT number if a truck rated 10,001 lb or more crosses state lines, and some states require one for local moves too. Read the weight rating on the door sticker before you buy."],["How do I get paid?","A common structure is a small deposit to hold the date and the balance by card once the move is done and checked. Never refuse to unload over a payment dispute. Check your state’s rules on deposits and written estimates."],["Should I take long-distance moves?","Not at first. Crossing a state line needs FMCSA authority, interstate insurance filings and federal paperwork, and the truck often drives home empty, which eats the profit. Get local moves running smoothly first, and pass long-distance jobs to a licensed interstate mover you trust."],["How do I compete with big moving companies?","Be the owner who answers the phone and shows up. Big van lines often use sales agents and different crews. Small movers win with fast video quotes, clear hourly pricing, the same crew from start to finish and strong reviews."]],tools:["Quoting and invoicing: SmartMoving, Supermove or Jobber, or a simple spreadsheet to start.","Estimating: video walkthroughs over FaceTime or Zoom, or a survey tool such as Yembo, plus an inventory list to estimate hours.","Reviews: a Google Business Profile with a short review link you text after every move.","Scheduling: a shared crew calendar that blocks end-of-month dates early, and a truck GPS that warns about low clearances."]},
'house-cleaning':{lic:["Rules vary by state and city. No state we know of has a special license for house cleaners, but most cities and counties require a general business license. Sales tax is where states differ: Texas taxes home cleaning sold by a cleaning company (with a narrow exception for some self-employed cleaners), New York taxes some interior cleaning, and Florida taxes only nonresidential cleaning. Confirm with your city and your state licensing board.","There’s no exam or experience requirement. Expect a business license form and fee, a home-occupation permit in some cities if you run the business from home, and a sales tax permit where cleaning is taxed. Insurance and a bond usually aren’t required by law, but property managers and many clients ask for proof before the first visit. Quotes and permits can take a few weeks, so start early.","You don’t need building permits, but how you sell is regulated. Many cities require a solicitation permit to go door to door, HOAs and gated communities often ban it, and putting flyers in mailboxes breaks federal law, because only mail with postage can go there. Use door hangers where they’re allowed.","The legal trap is paying helpers as 1099 contractors when the law sees them as employees. If you set their schedule, supply the products and tell them how to clean, they’re likely employees. California and Massachusetts use a strict ABC test. Misclassification can mean back payroll taxes, wage claims and penalties, so check your state’s test before you hire.","Once you hire, federal wage law counts drive time between clients’ homes during the workday as paid time, so pay for it and price it in. OSHA’s chemical hazard rules apply too: keep safety data sheets, label every spray bottle, and train your team never to mix bleach with ammonia or acids."],cost:[["Business setup (LLC, city license, janitorial bond)","$200–$1,000"],["General liability insurance","$400–$1,000 per year"],["Workers’ comp and payroll taxes","Depends on payroll and state; the biggest cost once you hire"],["Gloves, eye protection, step stool, safety data sheets","$100–$300"],["Commercial vacuum, microfiber, mops, caddies, starter chemicals","$400–$1,500"],["Used car or small van","$5,000–$15,000 if you don’t already own one"],["Booking software, website, marketing","$300–$1,500"],["Working capital for supplies and payroll until customers pay","$500–$3,000"]],costnote:"Bare minimum (you own a car, work solo, recurring residential cleans, insurance paid monthly) is roughly $1,500–$3,500. A team-ready start (two cleaners, a used van, two equipment kits and a month of payroll) is closer to $12,000–$25,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, get your city business license and check whether your state taxes cleaning. Get quotes for general liability and a janitorial bond."],["Weeks 3–4","Write a room-by-room checklist for standard, deep and move-out cleans. Time yourself cleaning 2–3 homes of friends or family so your hour estimates are real. Set up a Google Business Profile, a one-page site and online booking."],["Month 2","Do 5–10 one-time deep or move-out cleans and offer every happy client a weekly or every-other-week slot. Introduce yourself to 10 local realtors and property managers for move-in and move-out work. Ask each client for a review and a referral."],["Month 3","Build toward 8–12 recurring clients clustered in a few neighborhoods so drive time stays low. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Cleaners quote a flat price per visit, built from the labor hours a home takes. Example: a 2,000 sq ft home with 3 bedrooms and 2 bathrooms, cleaned every other week, takes about 3.5 labor hours. If labor costs you about $30 per hour (your pay or a cleaner’s wage plus payroll taxes and workers’ comp), that’s $105, plus about $15 for supplies and laundering cloths, for $120. Add 50–75% for overhead and profit (drive time, insurance, booking software, cancellations) and the price lands around $180–$210 per visit, plus sales tax where your state charges it. The first deep clean often takes 1.5–2 times as long, so quote it separately. Itemize the room-by-room checklist, the frequency, pet and clutter surcharges, and extras like inside the oven, inside the fridge and interior windows. Your own costs will differ, so treat this as an example.",mistakes:["Cleaning first and chasing payment later. Keep a card on file, charge on the day of the clean, and put your lockout and late-cancellation fees in writing.","Skipping insurance and a bond. One broken heirloom, scratched floor or theft claim can cost more than years of premiums.","No written checklist. Clean means something different to every client, so send a room-by-room checklist with every quote and leave a note about anything you couldn’t do.","Quoting a flat price over the phone, then walking into a home that hasn’t been cleaned in months. Quote the first visit as a deep clean, and add a line that time beyond the quote is billed at a set hourly rate after you check with the client.","Paying helpers as 1099 contractors when they work like employees, or not paying them for drive time between homes. Back wages, payroll taxes and penalties add up fast.","Letting quotes and one-time clients go cold. Follow up on every quote, and after each deep clean, offer a recurring slot. Many clients book on the second or third contact."],obj:[["“The last cleaner I called was cheaper.”","“That’s fair, I’d compare too. What did their price include? Ask whether it covers baseboards, inside the microwave, insurance and a bond. I’ll send my room-by-room checklist so you can compare line by line.”"],["“I want to get a few more quotes first.”","“That makes sense. What matters most to you in a cleaner? When you compare, ask who actually shows up, whether it’s the same person every visit, and what happens if something breaks. I’ll text you Thursday to answer any questions.”"],["“I need to talk to my partner first.”","“Of course, it’s their home too. What do you think they’ll ask about? I’ll send the checklist, the price per visit and my insurance details so you can go through it together.”"],["“Can you do every other week for the weekly price?”","“I see why you’d ask. How long has it been since the last full clean? Every-other-week visits take longer because more builds up, so they cost more per visit. I’ll send both prices side by side so you can pick what fits your budget.”"],["“I can just do it myself.”","“You definitely can. How many hours does it take you each week? Many clients keep the daily tidying and hand me the bathrooms, floors and kitchen. Want to try one clean and see what the time back is worth to you?”"],["“Maybe after the holidays.”","“Understood, it’s a busy time. Are you hosting anyone this year? Holiday weeks book up early, and the longer a home goes, the longer and pricier the first clean gets. I can do one deep clean now and start regular visits in January.”"],["“I’m not comfortable with a stranger in my house.”","“That’s completely fair. What would help you feel comfortable? I’m insured and bonded, I can share references, and the same person comes every visit. You don’t have to be home, but I’m happy to do a walkthrough with you before the first clean.”"],["“Why do you need my card on file?”","“Fair question. Would another way to pay suit you better? The card is charged only after each clean, with a receipt by text, and it covers the late-cancellation fee in my policy. I’ll send the policy so you can read it first.”"]],faq:[["Can I start with just one-time deep cleans?","Yes. Deep and move-out cleans pay well, show you how long homes really take and fill gaps in your week. But they don’t repeat, so offer every happy client a recurring slot. Steady weekly and every-other-week clients are what make the schedule work."],["Do I need a bond if I work alone?","Usually not by law. A janitorial bond mainly pays clients for theft by your employees, so it matters most once you hire. Many clients, property managers and HOAs ask for one anyway, and a small bond often costs about $100–$350 a year. Ask what your clients expect."],["How do I get paid?","Most cleaners keep a card on file and charge after each visit, or bill recurring clients weekly or monthly. Property managers may pay on net-30 terms, so plan for the wait. Put cancellation and lockout fees in writing, and check whether your state taxes cleaning."],["Should I take Airbnb turnover cleans?","They can fill weekdays, but they’re tight-window work: same-day check-ins, laundry, restocking and damage photos for the host. Price per turnover including laundry and restocking time, get the terms in writing, and don’t let last-minute bookings push out your recurring clients."],["How do I compete with big cleaning companies and apps?","Be the same face every time. Franchises and booking apps often rotate cleaners. Small owners win by sending the same person, answering texts quickly, following a clear checklist and building reviews in a few neighborhoods."]],tools:["Quoting, booking and invoicing: ZenMaid, Jobber or Housecall Pro, or a simple spreadsheet to start.","Estimating: a price sheet by bedrooms, bathrooms and square footage, checked against your own timed cleans. Zillow or Redfin listings confirm a home’s size before you quote.","Reviews: a Google Business Profile with a short review link you text after every clean.","Scheduling: a calendar with route planning (Google Maps or your booking software’s map view) to keep clients clustered, plus a key log that tags keys with codes, never addresses."]},
'car-detailing':{lic:["Rules vary by state and city. No state we know of has a special license for car detailers, but cities regulate mobile washing. Fort Worth, Texas, requires mobile cleaners to get a permit and follow wash-water practices, and Calabasas, California, requires a city permit for mobile car washes. Some states also tax detailing (Connecticut and Washington, for example), while many don’t. Confirm with your city and your state licensing board.","There’s no exam. Expect a business license, a sales tax permit where detailing is taxed, and in some cities a mobile wash permit that asks how you capture and dispose of wash water. Professional coating brands often require installer training before you can sell their coatings and warranties. This can take a few weeks, so start early.","Working on private property needs the owner’s permission. Apartment complexes, office parks and HOAs often ban mobile washing in their lots, some cities limit business activity on public streets, and many ban flyers on parked cars. Get the property manager’s OK in writing before you set up or market on site.","Letting wash water run into the street or a storm drain is an illegal discharge in many cities, even if it’s only soapy water. Cities enforce this under Clean Water Act stormwater permits and can fine you. Use a containment mat or a rinseless wash, and dispose of collected water into a sanitary sewer only where that’s allowed.","OSHA’s chemical hazard rules apply once you have employees: keep safety data sheets, label every dilution bottle and supply gloves and eye protection. Never run a generator in a garage or near open doors and windows, because carbon monoxide builds up fast. Wear a respirator when you apply coatings in an enclosed space."],cost:[["Business setup (LLC, business license, mobile wash permit)","$150–$1,000"],["General liability insurance","$500–$1,200 per year"],["Garagekeepers coverage for customers’ cars","$500–$2,500 per year; often bundled with liability"],["Safety gear (gloves, eye protection, respirator, spill kit)","$100–$300"],["Polisher, vacuum, extractor, pressure washer, water tank, generator","$1,000–$6,000"],["Used van or truck for a mobile rig","$8,000–$20,000 if you don’t already own one"],["Booking software, website, marketing","$300–$1,500"],["Working capital for chemicals, towels and coating stock","$300–$1,500"]],costnote:"Bare minimum (you own a truck or SUV, work solo and mobile, use the customer’s water and power, washes and full details only) is roughly $3,000–$5,000. A fully equipped mobile rig (a used van with water tank, generator, pressure washer, extractor and polishing gear) is closer to $15,000–$35,000. These are estimates, so get real quotes.",plan:[["Weeks 1–2","Register the LLC, get your EIN, open the bank account, and get quotes for liability and garagekeepers coverage. Call your city’s stormwater or public works office about mobile washing rules and permits."],["Weeks 3–4","Practice on your own car and 3–5 friends’ cars, timing each step. Build three packages priced by vehicle size. Set up a Google Business Profile, Instagram and online booking with deposits. Photograph every car before you touch it."],["Month 2","Do 10–15 maintenance washes and full details, and offer every happy customer a monthly maintenance plan. Introduce yourself to 5 used-car dealers and 5 office or apartment property managers who might let you work on site."],["Month 3","Add one-step paint correction once your results on test panels are consistent. Follow up on every quote within 48 hours and again at 5 days. Check which lead sources paid off and do more of those."]],price:"Detailers price per vehicle, by size class (sedan, small SUV, three-row SUV or truck) and condition. Example: a full interior and exterior detail on a three-row SUV in average condition takes about 5 labor hours. If labor costs you about $35 per hour (your pay or a tech’s wage plus payroll taxes and workers’ comp), that’s $175, plus about $25 for chemicals, pads and towels, for $200. Add 50–70% for overhead and profit (insurance, drive time, rig fuel, rain-outs, equipment wear) and the price lands around $300–$340. Itemize the interior (vacuum, extraction, leather, glass), the exterior (hand wash, decontamination, clay, sealant), wheels and tires, and add-ons like pet hair removal, odor treatment and engine bay. Set fixed fees for heavy pet hair, stains and sand, confirmed when you see the car. Your own costs will differ, so treat this as an example.",mistakes:["Taking bookings without a deposit. A Saturday no-show costs you a whole slot, so take a deposit online and collect the balance before you pack up.","Polishing customers’ paint before you’ve practiced, and relying on general liability alone. A burned panel edge or stained headliner usually isn’t covered without garagekeepers coverage, so practice on scrap panels first.","Skipping the walk-around. Photograph every panel, wheel and seat before you start, and note chips, scratches and stains on the work order, or you’ll be blamed for damage that was already there.","Quoting from a photo, then finding dog hair, sand and spilled drinks. Set fixed fees for pet hair, stains and heavy soil, and say on the booking form that the final price is confirmed when you see the car.","Letting wash water reach the street or a storm drain, or paying techs per car without checking minimum wage and overtime. Both can bring fines or back pay, so check your city’s and state’s rules first.","Letting quotes and one-time customers go cold. Follow up on every quote, and text each customer 4–6 weeks after a detail to book the next one. Most people won’t rebook unless you ask."],obj:[["“Another detailer quoted me $150.”","“Could be a good deal, and prices do vary. What does theirs include? Ask whether it’s a hand wash with clean mitts, clay and sealant, and real carpet extraction or just a vacuum. I’ll send my package list so you can compare.”"],["“I want to check a couple of other detailers.”","“Good idea. What matters most to you, the paint or the interior? Ask each one for before-and-after photos of a car like yours and proof of insurance. I’ll hold Saturday morning for you until Thursday.”"],["“I need to run it by the owner.”","“Makes sense. What will they look at first, price per car or turnaround time? I’ll send a one-page summary with per-vehicle pricing, turnaround and my insurance certificate. Could I do one car this week as a trial?”"],["“Can you knock something off?”","“I can fit a budget. What were you hoping to spend? I can do just the interior, or a wash and sealant instead of a full detail. What I won’t do is rush the wash, because that’s where swirl marks come from.”"],["“I’ll just take it through the car wash.”","“That’s quick, and fine between details. Have you noticed fine circles in the paint in direct sun? Brushes and dirty towels cause most of them. I can polish a test spot on your hood so you can see the difference before you decide.”"],["“I’ll wait until spring.”","“Understood. Is the car parked outside this winter? Salt and grime left on the paint and in the carpet all season get harder to remove. A wash and sealant now protects it until spring, and I can book your full detail for April.”"],["“What if you damage my car?”","“Fair question. What worries you most, the paint or the interior? I photograph the car before I start, test products on a hidden spot, and carry garagekeepers coverage for cars in my care. I’ll send the certificate before your appointment.”"],["“Why do you need a deposit to book?”","“Good question. Weekend slots fill fast, and a no-show costs me the whole morning. The deposit comes off your total, and you can move the booking free with 24 hours’ notice. Does that work for your schedule? I’ll send the booking link.”"]],faq:[["Can I start with just maintenance washes and interiors?","Yes. They need little gear, build reviews fast and turn into monthly plans. Add paint correction once you can polish test panels without burning edges or leaving haze."],["Do I need garagekeepers coverage if I work at the customer’s house?","Usually yes. The car is in your care while you work on it, and general liability often excludes that. Ask your agent for coverage that follows you to job sites, not just a listed address, and set limits that fit the cars you work on."],["How do I get paid?","Most detailers take a deposit at online booking and collect the balance by card when the job is done. Dealers and fleets often want a monthly invoice on net-15 or net-30 terms, so plan for the wait. Check whether your state charges sales tax on detailing."],["Should I offer ceramic coatings right away?","Not right away. Professional coatings with paint correction often sell for $1,000 or more, but a bad application leaves high spots you have to polish off, and a multi-year warranty is a promise you must keep. Get trained by the coating maker, practice on your own cars, and apply in shade or a garage where you control dust and heat."],["How do I compete with car washes and big detail shops?","Go to the customer. Busy owners pay to avoid losing half a day at a shop. Win with clear packages, photos of every job, quick replies and a monthly maintenance plan that keeps the car clean between full details."]],tools:["Quoting, booking and invoicing: Urable, OrbisX or Mobile Tech RX, which are built for detailers, or Square Appointments, or a simple spreadsheet to start.","Inspection: a paint depth gauge (such as a DeFelsko PosiTector or a budget digital gauge) to check the clear coat before you polish, plus a photo checklist of every panel at the walk-around.","Reviews: a Google Business Profile with a short review link you text after every detail, plus before-and-after posts on Instagram.","Scheduling: online booking with deposits, route planning to group jobs by area, and a weather app with hourly rain and heat forecasts so you can reschedule early."]}
});
function extra(t){var f=FULL[t.s];if(!f)return "";return "<div class='legal'><h2 style='margin-top:44px'>"+t.n+" deep dive</h2><h3>Licensing and rules</h3>"+L(f.lic)+"<h3>Itemized start-up costs</h3><div class='xs'><table class='cost'>"+f.cost.map(function(r){return "<tr><td>"+r[0]+"</td><td>"+r[1]+"</td></tr>"}).join("")+"</table></div><p>"+f.costnote+"</p><h3>Your first 90 days</h3>"+f.plan.map(function(r){return "<p><b style='color:var(--ink)'>"+r[0]+":</b> "+r[1]+"</p>"}).join("")+"<h3>Pricing example</h3><p>"+f.price+"</p><h3>Mistakes to avoid</h3>"+L(f.mistakes)+"<h3>Objection library</h3>"+Q(f.obj)+"<h3>Questions people ask</h3>"+Q(f.faq)+"<h3>Tools to consider</h3>"+L(f.tools)+"</div>"}
var app=document.getElementById("app"),done=[];
function get(s){try{return JSON.parse(localStorage.getItem("ft:"+s)||"[]")}catch(e){return[]}}
function put(s,v){try{localStorage.setItem("ft:"+s,JSON.stringify(v))}catch(e){}}
function find(s){return T.filter(function(t){return t.s===s})[0]}
function signup(label){return '<div class="signup" id="signup"><h2>Get the free '+label+' playbook</h2><p>Scripts, tips and objection answers for your trade. Enter your email and I’ll send it to you.</p><form id="f"><input type="email" id="em" required placeholder="you@example.com" aria-label="Your email"><button class="btn" type="submit">Send me the playbook</button></form><label><input type="checkbox" id="ok" form="f" required> I agree to receive the playbook and tips by email, and have read the <a href="#privacy">privacy policy</a>.</label><p id="fs" role="status"></p></div>'}
function wireSignup(label){var f=document.getElementById("f");if(!f)return;f.onsubmit=function(e){e.preventDefault();var b=f.querySelector("button"),ok=document.getElementById("ok"),st=document.getElementById("fs");b.disabled=true;st.textContent="Sending…";fetch(FORM_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({email:document.getElementById("em").value,guide:label,consent:ok.checked})}).then(function(r){if(!r.ok)throw r;f.style.display=ok.parentNode.style.display="none";st.textContent="Thanks! I’ll email your "+label+" playbook to you shortly."}).catch(function(){b.disabled=false;st.innerHTML="Sorry, that didn’t go through. Please try again, or email me at <a href='mailto:"+CONTACT+"'>"+CONTACT+"</a>."})}}
function tiles(list){return '<div class="grid">'+list.map(function(t){return '<a class="tile" href="#'+t.s+'"><b>'+t.n+'</b></a>'}).join("")+'</div>'}
function home(){
var h='<section class="hero"><div><h1>Start the business. Then get the jobs.</h1><p class="lead">Free step-by-step start-up guides for service trades, plus sales scripts and objection answers, so you can turn quote requests into booked work.</p><div class="cta"><a class="btn" href="#guides">Browse start-up guides</a><a class="btn ghost" href="#demo">See a sample objection</a></div></div><div class="thread" aria-label="Example text thread: a quote goes quiet, then a follow-up books the job"><div class="msg them">Hi, can you quote a roof repair? Leak over the garage.</div><div class="msg me">Sure. Total is $1,850, parts and labor.</div><div class="gap">6 days of silence</div><div class="msg me late" style="--i:0">Hi Mark, quick check-in. Is the garage leak still dripping? I have a Thursday slot if you want it fixed before the next rain.</div><div class="msg them late" style="--i:1">Yes! Thursday works. Sorry, got busy.</div></div></section>';
h+='<section><h2>What you’ll find here</h2><div class="cols"><div class="col"><h3>Start-up guides</h3><p>Costs, busy season and a checklist from LLC to first customers for ten trades.</p></div><div class="col"><h3>Objection handling</h3><p>Honest answers to “too expensive” and “I need to think about it.”</p></div><div class="col"><h3>Quote follow-up</h3><p>Most quotes go quiet, not “no.” Get messages that bring them back.</p></div></div></section>';
h+='<section id="demo"><h2>A sample objection handler</h2><p>Pick a trade.</p><div class="demo"><div class="tabs" id="tabs"></div><div class="card" aria-live="polite"><div class="q" id="q"></div><p class="a" id="a"></p></div></div></section>';
h+='<section><h2>Start-up guides by trade</h2>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section><div id="home-contact">'+signup("trade")+'</div>';
return h}
function guides(){return '<section><h1>Start-up guides</h1><p>Pick your trade for costs, busy season and a step-by-step checklist.</p>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section>'}
function guide(t){
done=get(t.s);
var h='<section><div class="crumbs"><a href="#guides">Guides</a> / '+CATS[t.c]+'</div><h1>How to start a '+t.n+' business</h1><div class="facts"><div class="fact"><h3>Start-up cost</h3><p>'+t.cost+'</p></div><div class="fact"><h3>Busy season</h3><p>'+t.season+'</p></div><div class="fact"><h3>Is it a good fit?</h3><p>'+t.fit+'</p></div><div class="fact"><h3>Where the money goes</h3><p>'+t.spend+'</p></div></div><p style="font-size:.9rem;color:var(--muted)">Costs are rough estimates. Rules vary by state. See the <a href="#disclaimer">disclaimer</a>.</p><h2>Step by step</h2><div class="prog" id="prog"></div><div class="bar"><i id="bar"></i></div><div style="height:16px"></div>';
STEPS.forEach(function(s,i){h+='<div class="step" id="st'+i+'"><button class="chk" data-i="'+i+'" aria-label="Mark step '+(i+1)+' completed"></button><div><h3>Step '+(i+1)+': '+s[0]+'</h3><p style="margin-bottom:0">'+s[1]+'</p><p class="tip"><b>'+(i===6?'Tips and tricks: ':'What to look for: ')+'</b>'+t.tips[i]+'</p></div></div>'});
h+=extra(t)+'</section>'+signup(t.n)+'<section><h2>Related guides</h2><div class="rel">'+T.filter(function(x){return x.c===t.c&&x.s!==t.s}).map(function(x){return '<a class="btn ghost" target="_blank" rel="noopener" href="'+PUBLIC+'#'+x.s+'">'+x.n+' guide</a>'}).join("")+'<a class="btn ghost" target="_blank" rel="noopener" href="'+PUBLIC+'#guides">All guides</a></div></section>';
return h}
function paint(t){STEPS.forEach(function(s,i){var e=document.getElementById("st"+i),on=done.indexOf(i)>-1;e.className="step"+(on?" done":"");e.firstChild.textContent=on?"✓":"";e.firstChild.setAttribute("aria-pressed",on)});document.getElementById("prog").textContent=done.length+" of 7 steps completed";document.getElementById("bar").style.width=(done.length/7*100)+"%"}
function render(id){
var t=find(id),h;
if(LEGAL[id])h='<section class="legal"><h1>'+LEGAL[id][0]+'</h1>'+LEGAL[id][1]+'</section>';
else if(id==="guides")h=guides();else if(t)h=guide(t);else{h=home();id="home"}
app.innerHTML=h;
if(t){paint(t);app.querySelectorAll(".chk").forEach(function(b){b.onclick=function(){var i=+b.dataset.i,k=done.indexOf(i);k>-1?done.splice(k,1):done.push(i);put(t.s,done);paint(t)}});wireSignup(t.n)}
else if(id==="home"){wireSignup("trade");var tb=document.getElementById("tabs");var sh=function(i){[].forEach.call(tb.children,function(b,k){b.setAttribute("aria-selected",k===i)});document.getElementById("q").textContent=OBJ[i][1];document.getElementById("a").textContent=OBJ[i][2]};OBJ.forEach(function(o,i){var b=document.createElement("button");b.type="button";b.textContent=o[0];b.onclick=function(){sh(i)};tb.appendChild(b)});sh(0)}
document.title=t?t.n+" start-up guide | FollowThrough":LEGAL[id]?LEGAL[id][0]+" | FollowThrough":id==="guides"?"Start-up guides | FollowThrough":"FollowThrough: start and sell a service business"}
function go(h){var id=(h||"").replace("#","")||"home";if(id==="moving-transportation")id="hauling-transportation";if(id==="home-contact"||id==="demo"){render("home");var s=document.getElementById(id==="demo"?"demo":"signup");if(s)s.scrollIntoView();return}render(id);window.scrollTo(0,0)}
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href^="#"]');if(a&&!a.target){e.preventDefault();try{history.replaceState(null,"",a.getAttribute("href"))}catch(x){}go(a.getAttribute("href"))}});
window.addEventListener("hashchange",function(){go(location.hash)});
go(location.hash);
</script>
</body>
</html>
